static void require(bool v,const char* why){if(!v)throw std::runtime_error(why);}
static std::vector<U8> read(const std::filesystem::path& p){std::ifstream f(p,std::ios::binary);require(bool(f),"Source-built original UI shader missing");return {std::istreambuf_iterator<char>(f),std::istreambuf_iterator<char>()};}
static std::vector<U8> blob(bool vertex,bool scalar=false,bool missing=false){const std::string uniform=missing?"[]":"[{\"binding\":0,\"block_size\":"+std::to_string(scalar?4:404)+",\"name\":\"Constants\"}]";const std::string metadata="{\"parameters\":{},\"input_semantics\":"+std::string(vertex?"[[0,0,0]]":"[]")+",\"reflection\":{\"ubos\":"+uniform+"}}";const std::string common="#include <metal_stdlib>\nusing namespace metal;\nstruct Params{float4 values[25];float tail;};\nbool paddingZero(constant Params& p){constant uchar* b=reinterpret_cast<constant uchar*>(&p);uint v=0;for(uint i=404;i<416;++i)v|=b[i];return v==0;}\nstruct V{float4 p[[position]];float4 uv[[user(locn0)]];float4 world[[user(locn3)]];float4 colour[[user(locn16)]];};\n";const std::string source=common+(vertex?"struct I{float2 p[[attribute(0)]];};vertex V blur_main(I i[[stage_in]],constant Params& u[[buffer(0)]]){return {float4(paddingZero(u)?i.p*u.tail:float2(99),.5,1),float4(i.p*.5+.5,0,0),float4(0,0,0,1),u.values[0]};}":scalar?"struct Scalar{float value;};fragment float4 blur_main(constant Scalar& u[[buffer(0)]]){return float4(u.value,0,0,1);}":"fragment float4 blur_main(constant Params& u[[buffer(0)]]){return paddingZero(u)?u.values[0]*u.tail:float4(1);}");const std::string entry="blur_main";std::vector<U8> b(40);std::memcpy(b.data(),"BMSL",4);auto word=[&](U32 p,U32 n){for(U32 i=0;i<4;++i)b[p+i]=U8(n>>(8*i));};word(4,1);word(8,vertex?0:1);word(16,40);word(20,metadata.size());word(24,40+metadata.size());word(28,source.size());word(32,40+metadata.size()+source.size());word(36,entry.size());b.insert(b.end(),metadata.begin(),metadata.end());b.insert(b.end(),source.begin(),source.end());b.insert(b.end(),entry.begin(),entry.end());word(12,b.size());return b;}
static void pixels(C_Surface& surface,U32 expected){auto p=surface.LockRect(16);require(p.pBits,"Uniform ABI GPU readback failed");bool good=true;for(U32 y=0;y<surface.GetHeight();++y)for(U32 x=0;x<surface.GetWidth();++x){U32 actual;std::memcpy(&actual,p.pBits+y*p.pitch+x*4,4);good&=actual==expected;}surface.UnlockRect();require(good,"Logical constants, reflected ABI tail padding or actual UI shader GPU pixels are wrong");}
int main(int argc,char** argv){try{
    require(argc==2,"Expected full source-built shader directory");const std::filesystem::path root=argv[1];C_MetalDevice device;require(device.Create(),"Uniform ABI Metal device failed");auto& c=device.GetContext();C_Surface colour;require(device.CreateSurface(19,11,E_Flags_Colour,E_SurfaceFormat_A8R8G8B8,E_Multisample_None,nullptr,&colour),"Uniform ABI target failed");C_VertexShader vs;C_PixelShader ps,scalar,flat,intensity,invalid;std::string error;auto v=blob(true),p=blob(false),s=blob(false,true),bad=blob(false,false,true),f=read(root/"ui/psPolygonFlat.bmsl"),i=read(root/"ui/psIntensityAsAlpha.bmsl");require(device.CreateVertexShader(v.size(),v.data(),0,&vs,nullptr,&error),error.c_str());for(auto pair:{std::make_pair(&ps,&p),std::make_pair(&scalar,&s),std::make_pair(&flat,&f),std::make_pair(&intensity,&i),std::make_pair(&invalid,&bad)})require(device.CreatePixelShader(pair.second->size(),pair.second->data(),0,pair.first,nullptr,&error),error.c_str());C_VertexDeclaration declaration;C_VertexFormat format;format.AddElement(0,0,E_VertexElementType_F32_2,E_VertexElementUsage_Position,0);C_VertexBuffer vertices;require(device.CreateVertexDeclaration(format,&declaration)&&device.CreateVertexBuffer(32,0,&vertices),"Uniform ABI geometry failed");const F32 quad[]={-1,1,1,1,-1,-1,1,-1};auto out=vertices.Lock();require(out,"Uniform ABI geometry map failed");std::memcpy(out,quad,sizeof(quad));vertices.Unlock();C_Texture texture;require(device.CreateTexture2D(1,1,1,0,E_TextureFormat_A8R8G8B8,&texture),"Original UI shader texture failed");auto tex=texture.Lock(0);require(tex.pBits,"Original UI texture map failed");std::memset(tex.pBits,255,4);texture.Unlock(0);c.SetColourSurface(0,&colour);c.SetVertexShader(&vs);c.SetVertexBuffer(0,&vertices,0,8,&declaration);c.SetDepthEnable(E_Bool_False);c.SetCullMode(E_CullMode_None);c.SetBlendEnable(E_Bool_False);c.SetColourWriteEnable(15);c.SetTexture(0,&texture);
    F32 constants[26*4]={};constants[0]=.25f;constants[1]=.5f;constants[2]=.75f;constants[3]=1;constants[23*4+3]=constants[24*4+3]=constants[25*4]=1;constants[101]=111;constants[102]=222;constants[103]=333;c.SetVertexShaderConstantF(0,constants,26);c.SetPixelShaderConstantF(0,constants,26);
    auto draw=[&](C_PixelShader& shader,U32 expected){c.SetPixelShader(&shader);c.BeginScene();c.Clear(E_Clear_Colour,0xff000000);c.DrawPrimitive(E_PrimitiveType_TriangleStrip,0,4);c.EndScene();pixels(colour,expected);};draw(ps,0xff4080bf);draw(scalar,0xff400000);draw(flat,0xff4080bf);draw(intensity,0xff4080bf);constants[0]=.75f;constants[1]=.25f;constants[2]=.5f;c.SetVertexShaderConstantF(0,constants,26);c.SetPixelShaderConstantF(0,constants,26);draw(ps,0xffbf4080);draw(flat,0xffbf4080);
    c.SetPixelShader(&invalid);c.BeginScene();bool rejected=false;try{c.DrawPrimitive(E_PrimitiveType_TriangleStrip,0,4);}catch(const std::logic_error&){rejected=true;}require(rejected,"Used compiled uniform without serialized metadata was silently fabricated");c.EndScene();c.SetColourSurface(0,nullptr);c.SetTexture(0,nullptr);device.Destroy(&texture);device.Destroy(&vertices);device.Destroy(&declaration);device.Destroy(&vs);for(auto* shader:{&ps,&scalar,&flat,&intensity,&invalid})device.Destroy(shader);device.Destroy(&colour);require(device.WaitIdle(),"Uniform ABI GPU completion failed");std::cout<<"Native constant ABI: compiled Metal reflection, vertex/pixel404-byte logical blocks with real416-byte aggregates, zero ABI tail despite nonzero register sentinels, scalar4-byte control, original UI Polygon/Intensity shaders, cached live updates and missing-binding rejection passed\n";return 0;
}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
